import React from 'react';
import { ResizableBox } from 'react-resizable';
import Draggable from 'react-draggable';
import 'react-resizable/css/styles.css';

const DraggableResizable = ({ children, defaultWidth, defaultHeight }) => (
  <Draggable>
    <ResizableBox width={defaultWidth} height={defaultHeight} minConstraints={[100, 100]} maxConstraints={[800, 800]}>
      {children}
    </ResizableBox>
  </Draggable>
);

export default DraggableResizable;
